#!/usr/bin/env python3"""Скрипт для редактирования промптов агентов"""import sysimport os# Добавляем родительскую директорию в путь Pythonparent_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))sys.path.insert(0, parent_dir)from sqlmodel import Session, selectfrom core.database import enginefrom models.agent import Agentdef edit_agent_prompt():    """Редактировать промпт агента"""        with Session(engine) as session:        agents = session.exec(select(Agent)).all()                print("=" * 80)        print("🤖 РЕДАКТИРОВАНИЕ ПРОМПТОВ АГЕНТОВ")        print("=" * 80)                # Показываем список агентов        for i, agent in enumerate(agents, 1):            print(f"{i}. {agent.name} (ID: {agent.id})")                try:            choice = int(input(f"\nВыберите агента для редактирования (1-{len(agents)}): "))            if 1 <= choice <= len(agents):                selected_agent = agents[choice - 1]                                print(f"\nТекущий промпт для {selected_agent.name}:")                print("-" * 60)                print(selected_agent.instructions)                print("-" * 60)                                print("\nВведите новый промпт (или нажмите Enter для отмены):")                new_prompt = input()                                if new_prompt.strip():                    selected_agent.instructions = new_prompt.strip()                    session.add(selected_agent)                    session.commit()                    print(f"✅ Промпт для {selected_agent.name} обновлен!")                else:                    print("❌ Редактирование отменено")            else:                print("❌ Неверный выбор")                        except ValueError:            print("❌ Введите корректный номер")        except Exception as e:            print(f"❌ Ошибка: {e}")def add_new_agent():    """Добавить нового агента"""        print("\n" + "=" * 80)    print("➕ ДОБАВЛЕНИЕ НОВОГО АГЕНТА")    print("=" * 80)        name = input("Имя агента: ").strip()    if not name:        print("❌ Имя не может быть пустым")        return        print("\nДоступные модели:")    print("1. openrouter/anthropic/claude-3.5-sonnet")    print("2. deepseek/deepseek-chat-v3.1")    print("3. meta-llama/llama-3.1-8b-instruct")        model_choice = input("Выберите модель (1-3): ").strip()    models = {        "1": "openrouter/anthropic/claude-3.5-sonnet",        "2": "deepseek/deepseek-chat-v3.1",         "3": "meta-llama/llama-3.1-8b-instruct"    }        model = models.get(model_choice, "openrouter/anthropic/claude-3.5-sonnet")        print("\nВведите промпт (инструкции) для агента:")    print("(Можете вводить многострочный текст, завершите пустой строкой)")        instructions_lines = []    while True:        line = input()        if line == "":            break        instructions_lines.append(line)        instructions = "\n".join(instructions_lines)        if not instructions.strip():        print("❌ Промпт не может быть пустым")        return        with Session(engine) as session:        new_agent = Agent(            name=name,            instructions=instructions,            model=model        )                session.add(new_agent)        session.commit()        session.refresh(new_agent)                print(f"✅ Агент '{new_agent.name}' создан с ID: {new_agent.id}")def main():    """Главное меню"""        while True:        print("\n" + "=" * 80)        print("🔧 УПРАВЛЕНИЕ ПРОМПТАМИ АГЕНТОВ")        print("=" * 80)        print("1. Просмотреть все промпты")        print("2. Редактировать промпт агента")        print("3. Редактировать изображение агента")        print("4. Добавить нового агента")        print("5. Выход")                choice = input("\nВыберите действие (1-5): ").strip()                if choice == "1":            view_all_prompts()        elif choice == "2":            edit_agent_prompt()        elif choice == "3":            edit_agent_image()        elif choice == "4":            add_new_agent()        elif choice == "5":            print("👋 До свидания!")            break        else:            print("❌ Неверный выбор")def view_all_prompts():    """Показать все промпты агентов"""        with Session(engine) as session:        agents = session.exec(select(Agent)).all()                print("\n" + "=" * 80)        print("🤖 ПРОМПТЫ ВСЕХ АГЕНТОВ")        print("=" * 80)                for i, agent in enumerate(agents, 1):            print(f"\n{i}. АГЕНТ: {agent.name}")            print(f"   ID: {agent.id}")            print(f"   Модель: {agent.model}")            print(f"   Создан: {agent.created_at}")            print("-" * 60)            print("ПРОМПТ:")            print(agent.instructions)            print("-" * 60)                print(f"\nВсего агентов: {len(agents)}")def edit_agent_image():    """Редактировать изображение агента"""        with Session(engine) as session:        agents = session.exec(select(Agent)).all()                print("=" * 80)        print("🖼️ РЕДАКТИРОВАНИЕ ИЗОБРАЖЕНИЙ АГЕНТОВ")        print("=" * 80)                # Показываем список агентов        for i, agent in enumerate(agents, 1):            image_status = "📷" if agent.image_url else "❌"            print(f"{i}. {image_status} {agent.name} (ID: {agent.id})")            if agent.image_url:                print(f"   Текущее изображение: {agent.image_url}")                try:            choice = int(input(f"\nВыберите агента для редактирования изображения (1-{len(agents)}): "))            if 1 <= choice <= len(agents):                selected_agent = agents[choice - 1]                                print(f"\nТекущее изображение для {selected_agent.name}:")                if selected_agent.image_url:                    print(f"URL: {selected_agent.image_url}")                else:                    print("Изображение не установлено")                                print("\nПримеры URL изображений:")                print("• https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&h=150&fit=crop&crop=face")                print("• https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face")                print("• https://images.unsplash.com/photo-1494790108755-2616b612b786?w=150&h=150&fit=crop&crop=face")                                new_image_url = input(f"\nВведите новый URL изображения для {selected_agent.name} (или Enter для удаления): ").strip()                                selected_agent.image_url = new_image_url if new_image_url else None                session.add(selected_agent)                session.commit()                                if new_image_url:                    print(f"✅ Изображение для {selected_agent.name} обновлено!")                else:                    print(f"✅ Изображение для {selected_agent.name} удалено!")            else:                print("❌ Неверный выбор!")        except ValueError:            print("❌ Введите корректный номер!")        except Exception as e:            print(f"❌ Ошибка: {e}")if __name__ == "__main__":    main()